// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { Icon } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Foundations/Icon)

figma.connect(Icon, FIGMA_NODE_URL, {
  props: {
    icon: figma.boolean('hasIcon', { true: figma.instance('icon'), false: undefined }),
    label: figma.string('label'),
    name: figma.string('name'),
    style: figma.enum('style', { 'light': 'light', 'regular': 'regular', 'solid': 'solid' }),
    size: figma.enum('size', { '12': 12, '14': 14, '16': 16, '18': 18 }),
  },
  example: ({ label, icon, name, style, size }) => (
    <Icon icon={icon} name={name} style={style} size={size}>{label}</Icon>
  ),
});
